const CH = { app: ['APP', 'Pesan Aplikasi'], dash: ['DSB', 'Pesan Dashboard'], push: ['PSH', 'Push'], wa: ['WA', 'WhatsApp'], ig: ['IG', 'Instagram'], fb: ['FB', 'Facebook'], email: ['EM', 'Email'], tg: ['TG', 'Telegram'], web: ['WEB', 'Web Chat'] };
const chanBadge = c => `<span class="chan ${c === 'email' ? 'em' : c}" title="${CH[c][1]}" aria-label="${CH[c][1]}">${CH[c][0]}</span>`;
