  list() { return CONVERSATIONS.filter(c => (this.tab === 'all' || (this.tab === 'unassigned' ? !c.assignee : this.tab === 'assigned' ? !!c.assignee : c.sla != null && c.sla < 0)) && (this.chan === 'all' || c.channel === this.chan) && (this.status === 'all' || (this.status === 'active' ? ['open', 'pending'].includes(c.status) : c.status === this.status)) && (!this.q || (c.contact + c.id + c.messages.map(m => m.text).join(' ')).toLowerCase().includes(this.q.toLowerCase()))).sort((a, b) => b.ts - a.ts); },
