function msgHTML(m) { if (m.dir === 'sys') return `<div class="msg sys">${ic('zap', 'sm')} ${esc(m.text)} · ${esc(fDT(m.ts))}</div>`; if (m.dir === 'note') return `<div class="msg note"><b>${ic('lock', 'sm')} ${L3(['Catatan internal', 'Internal note', 'ملاحظة داخلية'])} · ${esc(m.by)}</b><div>${esc(m.text)}</div><div class="mt">${esc(fDT(m.ts))} · ${L3(['tidak terlihat oleh kontak', 'not visible to contact', 'غير مرئية للعميل'])}</div></div>`; return `<div class="msg ${m.dir}">${esc(m.text)}<div class="mt">${m.by ? esc(m.by) + ' · ' : ''}${esc(fD(m.ts, { hour: '2-digit', minute: '2-digit' }))}${typeof omniTick === 'function' ? omniTick(m) : ''}</div></div>`; }
