function wzCollect() { const g = id => document.getElementById(id); if (g('wz-name')) WZ.name = g('wz-name').value; if (g('wz-owner')) { if (WZ.owner !== g('wz-owner').value) { WZ.owner = g('wz-owner').value; const p = PACKAGES.find(p => p.travel === WZ.owner); WZ.pkg = p ? p.id : null; } else if (g('wz-pkg')) WZ.pkg = g('wz-pkg').value; } if (g('wz-aud')) WZ.audience = g('wz-aud').value; if (g('wz-lal')) WZ.lookalike = g('wz-lal').checked; if (g('wz-land')) WZ.landing = g('wz-land').value; if (g('wz-bud')) WZ.budget = +g('wz-bud').value || WZ.budget; if (g('wz-day')) WZ.daily = +g('wz-day').value || WZ.daily; if (g('wz-start')) WZ.start = g('wz-start').value; if (g('wz-end')) WZ.end = g('wz-end').value; }
